-- Evaluation-ready schema. Apply only after creating/connecting a Supabase project.
create extension if not exists pgcrypto;
alter default privileges for role postgres in schema public revoke select,insert,update,delete on tables from anon,authenticated;
alter default privileges for role postgres in schema public revoke usage,select on sequences from anon,authenticated;
create table if not exists public.sources(id text primary key,name text not null,url text not null check(url ~ '^https://'),publisher text not null,accessed_on date not null default current_date);
create table if not exists public.conditions(id text primary key,crop text not null,name text not null,condition_type text not null check(condition_type in('Disease','Pest','Nutrient stress','Healthy')),affected_parts text[] not null,symptoms text[] not null,confirmation text not null,actions text[] not null,source_id text not null references public.sources(id),review_status text not null default 'reviewed' check(review_status in('draft','reviewed','retired')),updated_at timestamptz not null default now());
create table if not exists public.model_versions(id text primary key,classes text[] not null,dataset_ref text not null,metrics jsonb not null default '{}'::jsonb,artifact_sha256 text,validated_at timestamptz,active boolean not null default false);
create table if not exists public.plant_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,field_name text not null,row_code text not null,plant_code text not null,latitude numeric,longitude numeric,created_at timestamptz not null default now(),unique(user_id,field_name,row_code,plant_code));
create table if not exists public.inspections(id uuid primary key default gen_random_uuid(),plant_record_id uuid not null references public.plant_records(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,condition_key text not null,decision_source text not null check(decision_source in('image_model','symptom_guide','expert')),confidence numeric check(confidence between 0 and 1),severity text check(severity in('mild','moderate','severe')),model_version text references public.model_versions(id),image_path text,review_state text not null default 'unreviewed' check(review_state in('unreviewed','confirmed','corrected','rejected')),created_at timestamptz not null default now());
create table if not exists public.feedback(id uuid primary key default gen_random_uuid(),inspection_id uuid not null references public.inspections(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,proposed_label text,expert_label text,consent_for_training boolean not null default false,reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.treatment_plans(id uuid primary key default gen_random_uuid(),inspection_id uuid not null references public.inspections(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,area_acres numeric not null check(area_acres>0),label_rate_per_acre numeric not null check(label_rate_per_acre>0),rate_unit text not null check(rate_unit in('ml','g','kg','litre')),reference text not null check(length(trim(reference))>0),total_quantity numeric generated always as (area_acres*label_rate_per_acre) stored,farmer_approved_at timestamptz,applied_at timestamptz,created_at timestamptz not null default now());
alter table public.sources enable row level security;alter table public.conditions enable row level security;alter table public.model_versions enable row level security;alter table public.plant_records enable row level security;alter table public.inspections enable row level security;alter table public.feedback enable row level security;alter table public.treatment_plans enable row level security;
grant select on public.sources,public.conditions,public.model_versions to anon,authenticated;
grant select,insert,update,delete on public.plant_records,public.inspections,public.feedback,public.treatment_plans to authenticated;
create policy "public reads reviewed sources" on public.sources for select to anon,authenticated using(true);
create policy "public reads reviewed conditions" on public.conditions for select to anon,authenticated using(review_status='reviewed');
create policy "public reads validated model metadata" on public.model_versions for select to anon,authenticated using(validated_at is not null);
create policy "owners manage plants" on public.plant_records for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "owners manage inspections" on public.inspections for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "owners manage feedback" on public.feedback for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "owners manage treatment plans" on public.treatment_plans for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create index if not exists inspections_plant_time_idx on public.inspections(plant_record_id,created_at desc);
create index if not exists conditions_crop_parts_idx on public.conditions(crop) include(name,condition_type,affected_parts);
create index if not exists feedback_review_idx on public.feedback(reviewed_at) where reviewed_at is null;
create index if not exists treatment_plans_inspection_time_idx on public.treatment_plans(inspection_id,created_at desc);
